DROP POLICY "Course instructors create mark drafts" ON public.assignment_mark_drafts;
CREATE POLICY "Course instructors create mark drafts" ON public.assignment_mark_drafts FOR INSERT TO authenticated WITH CHECK (trainer_id = auth.uid() AND EXISTS (SELECT 1 FROM public.assignment_submissions s JOIN public.assignments a ON a.id = s.assignment_id WHERE s.id = assignment_mark_drafts.submission_id AND public.teaches(auth.uid(), a.course_slug) AND (assignment_mark_drafts.score IS NULL OR assignment_mark_drafts.score BETWEEN 0 AND a.max_score)));
DROP POLICY "Course instructors edit mark drafts" ON public.assignment_mark_drafts;
CREATE POLICY "Course instructors edit mark drafts" ON public.assignment_mark_drafts FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.assignment_submissions s JOIN public.assignments a ON a.id = s.assignment_id WHERE s.id = assignment_mark_drafts.submission_id AND public.teaches(auth.uid(), a.course_slug))) WITH CHECK (trainer_id = auth.uid() AND EXISTS (SELECT 1 FROM public.assignment_submissions s JOIN public.assignments a ON a.id = s.assignment_id WHERE s.id = assignment_mark_drafts.submission_id AND public.teaches(auth.uid(), a.course_slug) AND (assignment_mark_drafts.score IS NULL OR assignment_mark_drafts.score BETWEEN 0 AND a.max_score)));